{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — {{TAGLINE}}</title>
  <meta name="description" content="Clinical, safety-first aromatherapy consultations and custom blends in {{CITY}}, {{STATE}}. Hybrid services: in-person + virtual." />
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body class="site-root">
  <header class="nav-outer">
    <div class="nav-inner">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <button id="nav-toggle" aria-label="Toggle navigation">☰</button>
      <nav class="main-nav" id="main-nav">
        <a href="/">Home</a>
        <a href="/services.html">Offerings</a>
        <a href="/blends.html">Blends &amp; Profiles</a>
        <a href="/shop.html">Shop</a>
        <a href="/pricing.html">Rates</a>
        <a href="/about.html">About</a>
        <a href="/book.html" class="cta-link">Book</a>
        <a href="/contact.html">Connect</a>
      </nav>
    </div>
  </header>

  <main>
    <!-- Hero: safety-forward, clinical calm -->
    <section class="hero" style="background-image: url('assets/img/pattern.svg');">
      <div class="hero-card glass">
        <h1 class="hero-title">Careful, scent-led support for everyday wellbeing</h1>
        <p class="hero-sub">{{TAGLINE}} — a clinical, safety-first approach to personalised aromatherapy with hybrid sessions.</p>
        <div class="hero-actions">
          <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <a class="btn ghost" href="/about.html">Meet {{PRACTITIONER_NAME}}</a>
        </div>
        <p class="safety-note">Not a medical service: aromatherapy is supportive and complementary. Consult your healthcare provider for medical advice.</p>
      </div>
    </section>

    <!-- Diagnostic: guided intake -->
    <section id="diagnostic" class="section">
      <div class="section-card glass">
        <h2>Start with a brief screening</h2>
        <p class="muted">A short, safety-focused questionnaire helps us recommend appropriate blends and delivery methods. Your answers remain private.</p>
        <form id="intake-form" class="intake" onsubmit="return false;">
          <label>Do you have known allergies to plant extracts or essential oils?
            <select name="allergy" id="allergy" required>
              <option value="">Choose...</option>
              <option value="no">No</option>
              <option value="yes">Yes</option>
            </select>
          </label>
          <label>Are you pregnant, breastfeeding, or under the care of a physician for a chronic condition?
            <select name="pregnancy" id="pregnancy" required>
              <option value="">Choose...</option>
              <option value="no">No</option>
              <option value="yes">Yes</option>
            </select>
          </label>
          <label>Do you have pets? (we'll suggest pet-safe options)
            <select name="pets" id="pets" required>
              <option value="">Choose...</option>
              <option value="no">No</option>
              <option value="yes">Yes</option>
            </select>
          </label>
          <div class="form-actions">
            <button type="button" class="btn" id="screen-submit">Review suggestions</button>
            <a class="small-link" href="/blends.html">Browse blends</a>
          </div>
        </form>
        <p class="advisory">Safety reminders: dilution and patch testing are recommended. For any pregnancy or pediatric questions, we provide tailored guidance — always consult a medical professional first.</p>
      </div>
    </section>

    <!-- Plan: hybrid offering details -->
    <section id="plan" class="section alt">
      <div class="section-grid">
        <div class="glass plan-card">
          <h3>Hybrid consultations</h3>
          <p>Combine virtual intake and in-person blending for a precise, practical plan. Sessions include a safety review, aromatic profiling, and a personalized dilution protocol.</p>
          <ul>
            <li>Initial intake (30–45 min): remote form + live review</li>
            <li>Customization (30 min): blend formulation and dilution guidance</li>
            <li>Follow-up (15–20 min): tweak and support</li>
          </ul>
        </div>
        <div class="glass plan-card">
          <h3>What we provide</h3>
          <p>Clinical knowledge, evidence-aware guidance, and practical product options. We do not make medical claims or replace professional medical care.</p>
          <p class="muted">All blends include clear labeling with recommended dilution ranges and patch test instructions.</p>
        </div>
      </div>
    </section>

    <!-- Micro habits: daily practices -->
    <section id="micro_habits" class="section">
      <div class="section-card glass">
        <h2>Micro-habits for scent harmony</h2>
        <p class="muted">Small, reproducible practices support safe and enjoyable aromatherapy use.</p>
        <ol class="habits">
          <li>Patch test a diluted sample on inner forearm for 24 hours before regular use.</li>
          <li>Start with low dilution (0.5–2%) for daily topical support; increase cautiously if appropriate.</li>
          <li>Prefer short diffusing sessions (10–30 minutes) and ventilate the room.</li>
          <li>Store oils in a cool, dark place away from pets and children.</li>
        </ol>
        <p class="muted small">If you have pets or pregnancy considerations, see our guidance or book a consultation.</p>
      </div>
    </section>

    <!-- Pricing: simple tiered pricing -->
    <section id="pricing" class="section alt">
      <div class="section-card glass">
        <h2>Transparent pricing</h2>
        <p class="muted">Hybrid packages and single sessions — designed for clarity and flexibility.</p>
        <div class="pricing-grid">
          <div class="price-card glass">
            <h4>Intro Session</h4>
            <p class="price">$75</p>
            <p>30-minute virtual intake and safety screen. A concise plan and next steps.</p>
            <a class="btn" href="/book.html">Book Intro</a>
          </div>
          <div class="price-card featured glass">
            <h4>Full Consultation</h4>
            <p class="price">$165</p>
            <p>Hybrid: intake + blend formulation + dilution protocol. Includes one follow-up message.</p>
            <a class="btn primary" href="/book.html">Reserve</a>
          </div>
          <div class="price-card glass">
            <h4>Blend Top-up</h4>
            <p class="price">$45</p>
            <p>Order a refill or schedule a short review to adjust your blend.</p>
            <a class="btn" href="/shop.html">Shop Blends</a>
          </div>
        </div>
        <p class="safety-note">Prices valid as displayed. Not billed as medical services.</p>
      </div>
    </section>

    <!-- CTA: clear booking prompt -->
    <section id="cta" class="section cta-section">
      <div class="cta-card glass">
        <h2>Ready to begin a thoughtful, safety-first aromatherapy plan?</h2>
        <p>Book a hybrid session or request a sample blend. We prioritize gentle protocols and clear guidance.</p>
        <div class="cta-actions">
          <a class="btn primary large" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <a class="btn ghost" href="/contact.html">Contact {{PRACTITIONER_NAME}}</a>
        </div>
        <p class="muted">Serving {{CITY}}, {{STATE}} and virtual clients. Phone: {{PHONE}} • Email: {{EMAIL}}</p>
      </div>
    </section>
  </main>

  <footer class="site-footer">
    <div class="footer-inner">
      <div class="footer-brand">
        <strong>{{BUSINESS_NAME}}</strong>
        <span class="muted">Hybrid aromatherapy consultations — safety-forward support</span>
      </div>
      <nav class="footer-nav">
        <a href="/services.html">Services</a>
        <a href="/blends.html">Blends</a>
        <a href="/shop.html">Shop</a>
        <a href="/contact.html">Contact</a>
      </nav>
      <div class="footer-contact">
        <a href="tel:{{PHONE}}">{{PHONE}}</a>
        <a href="mailto:{{EMAIL}}">{{EMAIL}}</a>
      </div>
    </div>
    <div class="copyright">© <span id="year">2026</span> {{BUSINESS_NAME}} — Not a substitute for medical care.</div>
  </footer>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
