{"path":"assets/css/styles.css","content":"/* Glass morphism clinical-calm stylesheet */
:root{
  --bg:#0f1724;
  --card-bg: rgba(255,255,255,0.06);
  --glass-border: rgba(255,255,255,0.08);
  --accent: #6cd3b2;
  --accent-2: #8ab4ff;
  --muted: rgba(255,255,255,0.68);
  --max-width:1100px;
}
*{box-sizing:border-box}
html,body{height:100%;margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial; background: linear-gradient(180deg,#061021 0%, #071726 100%); color:#e6eef6}
.site-root{min-height:100vh;display:flex;flex-direction:column}
.nav-outer{backdrop-filter: blur(6px);border-bottom:1px solid var(--glass-border);}
.nav-inner{max-width:var(--max-width);margin:0 auto;padding:12px 18px;display:flex;align-items:center;justify-content:space-between}
.brand{font-weight:700;color:var(--accent-2);text-decoration:none}
#nav-toggle{display:none;background:transparent;border:0;color:var(--muted);font-size:20px}
.main-nav a{margin:0 10px;color:var(--muted);text-decoration:none}
.main-nav a.cta-link{background:linear-gradient(90deg,var(--accent),var(--accent-2));padding:8px 12px;border-radius:8px;color:#052028}
.hero{padding:48px 18px;background-size:cover;background-position:center}
.hero-card{max-width:var(--max-width);margin:0 auto;padding:36px;border-radius:14px}
.glass{background:var(--card-bg);border:1px solid var(--glass-border);backdrop-filter:blur(10px);box-shadow:0 6px 30px rgba(2,8,23,0.6)}
.hero-title{font-size:28px;margin:0 0 8px}
.hero-sub{margin:0 0 16px;color:var(--muted)}
.hero-actions{display:flex;gap:12px;margin-bottom:12px}
.btn{display:inline-block;padding:10px 14px;border-radius:10px;text-decoration:none;color:inherit;border:1px solid rgba(255,255,255,0.06)}
.btn.ghost{background:transparent}
.btn.primary{background:linear-gradient(90deg,var(--accent),var(--accent-2));color:#052028;border:0}
.btn.large{padding:14px 20px;font-weight:700}
.safety-note{font-size:12px;color:var(--muted)}
.section{padding:36px 18px}
.section.alt{background:linear-gradient(180deg, rgba(255,255,255,0.02), transparent)}
.section-card{max-width:var(--max-width);margin:0 auto;padding:20px;border-radius:12px}
.section-grid{max-width:var(--max-width);margin:0 auto;display:grid;grid-template-columns:1fr;gap:16px}
.plan-card{padding:18px}
@media(min-width:800px){
  .section-grid{grid-template-columns:1fr 1fr}
  #nav-toggle{display:none}
}
.intake{display:grid;gap:10px}
.intake label{display:flex;flex-direction:column;color:var(--muted);font-size:14px}
.form-actions{display:flex;gap:8px;align-items:center;margin-top:6px}
.muted{color:var(--muted)}
.pricing-grid{display:grid;grid-template-columns:1fr;gap:12px;margin-top:12px}
.price-card{padding:14px}
.price-card.featured{transform:translateY(-6px);border:1px solid rgba(255,255,255,0.09)}
.price{font-size:20px;font-weight:700;margin:6px 0}
.pricing-grid .btn{margin-top:8px}
@media(min-width:900px){.pricing-grid{grid-template-columns:repeat(3,1fr)}}
.habits{margin:12px 0 0;padding-left:18px;color:var(--muted)}
.cta-section{padding:28px 18px}
.cta-card{max-width:var(--max-width);margin:0 auto;padding:20px;text-align:center}
.cta-actions{display:flex;gap:12px;justify-content:center;margin-top:12px}
.footer-inner{max-width:var(--max-width);margin:0 auto;padding:18px;display:flex;justify-content:space-between;align-items:center}
.footer-nav a{margin:0 8px;color:var(--muted);text-decoration:none}
.site-footer{border-top:1px solid var(--glass-border);padding-top:12px}
.footer-contact a{display:block;color:var(--muted);text-decoration:none}
.copyright{max-width:var(--max-width);margin:12px auto 24px;color:var(--muted);font-size:13px;text-align:center}
/* Responsive nav */
@media(max-width:799px){
  #nav-toggle{display:block}
  .main-nav{position:fixed;right:12px;top:56px;background:rgba(3,8,15,0.9);padding:12px;border-radius:10px;display:none;flex-direction:column}
  .main-nav.open{display:flex}
  .nav-inner{padding:12px}
}
/* small utility */
.small-link{font-size:13px;color:var(--accent-2);text-decoration:underline}
.muted.small{font-size:13px}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Mobile nav toggle
  var toggle=document.getElementById('nav-toggle');
  var nav=document.getElementById('main-nav');
  if(toggle && nav){
    toggle.addEventListener('click',function(){
      nav.classList.toggle('open');
    });
  }

  // Intake quick screen -> suggest simple guidance (safety-forward)
  var submit=document.getElementById('screen-submit');
  if(submit){
    submit.addEventListener('click',function(){
      var allergy=document.getElementById('allergy').value;
      var pregnancy=document.getElementById('pregnancy').value;
      var pets=document.getElementById('pets').value;
      var msg='Suggested next steps:\n';
      if(allergy==='yes') msg += '- We recommend a conservative patch-test and consulting for specific allergens.\n';
      else msg += '- No known allergies: proceed with low dilutions and patch tests.\n';
      if(pregnancy==='yes') msg += '- Pregnancy/breastfeeding: we offer tailored guidance; book a consult before regular use.\n';
      if(pets==='yes') msg += '- Pets at home: we will prioritise pet-safe profiles and diffusion limits.\n';
      msg += '\nFor personalised plans and labeled dilutions, please book a Full Consultation.';
      alert(msg);
    });
  }

  // Smooth scroll for anchor links
  document.querySelectorAll('a[href^="#"]').forEach(function(a){
    a.addEventListener('click',function(e){
      e.preventDefault();
      var t=document.querySelector(this.getAttribute('href'));
      if(t) t.scrollIntoView({behavior:'smooth'});
    });
  });

  // Year in footer
  var year=document.getElementById('year'); if(year) year.textContent=new Date().getFullYear();
})();"} 
